// Initialize run tracking
const runId = `run_${Date.now()}`;
const runTimestamp = new Date().toISOString();

return [{
  json: {
    run_id: runId,
    run_timestamp: runTimestamp,
    accounts_processed: 0,
    accounts_success: 0,
    accounts_failed: 0,
    green_count: 0,
    yellow_count: 0,
    red_count: 0,
    errors: [],
    config: $input.first().json
  }
}];

// Generate 10 synthetic demo accounts with varied health profiles
const today = new Date();

function addDays(date, days) {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result.toISOString().split('T')[0];
}

function randomBetween(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

const profiles = [
  // 3 Healthy accounts (Green)
  { health: 'green', usageMult: 1.1, tickets: 1, nps: 9, sentiment: 0.7, championDays: 3, csmDays: 5, failedPayments: 0, renewal: 120 },
  { health: 'green', usageMult: 1.2, tickets: 0, nps: 10, sentiment: 0.8, championDays: 2, csmDays: 3, failedPayments: 0, renewal: 180 },
  { health: 'green', usageMult: 1.0, tickets: 2, nps: 9, sentiment: 0.6, championDays: 5, csmDays: 7, failedPayments: 0, renewal: 90 },

  // 4 Mild Risk accounts (Yellow)
  { health: 'yellow', usageMult: 0.75, tickets: 3, nps: 7, sentiment: 0.3, championDays: 15, csmDays: 12, failedPayments: 0, renewal: 75 },
  { health: 'yellow', usageMult: 0.85, tickets: 4, nps: 6, sentiment: 0.2, championDays: 10, csmDays: 18, failedPayments: 0, renewal: 55 },
  { health: 'yellow', usageMult: 0.90, tickets: 6, nps: 7, sentiment: 0.1, championDays: 8, csmDays: 10, failedPayments: 1, renewal: 100 },
  { health: 'yellow', usageMult: 0.80, tickets: 2, nps: 5, sentiment: -0.1, championDays: 20, csmDays: 8, failedPayments: 0, renewal: 40 },

  // 3 Severe Risk accounts (Red)
  { health: 'red', usageMult: 0.45, tickets: 9, nps: 3, sentiment: -0.6, championDays: 45, csmDays: 35, failedPayments: 2, renewal: 25 },
  { health: 'red', usageMult: 0.35, tickets: 12, nps: 2, sentiment: -0.7, championDays: 60, csmDays: 28, failedPayments: 3, renewal: 15 },
  { health: 'red', usageMult: 0.55, tickets: 7, nps: 4, sentiment: -0.4, championDays: 35, csmDays: 40, failedPayments: 1, renewal: 20 }
];

const companyNames = [
  'Acme Corp', 'TechStart Inc', 'Global Solutions', 'DataDriven Co',
  'CloudFirst Ltd', 'Innovate Labs', 'Enterprise Plus', 'ScaleUp Systems',
  'NextGen Tech', 'Alpha Industries'
];

const tiers = ['enterprise', 'growth', 'starter'];
const csms = [
  { email: 'redacted@example.com', name: 'Jane Smith' },
  { email: 'redacted@example.com', name: 'Mike Johnson' },
  { email: 'redacted@example.com', name: 'Sarah Williams' }
];

const accounts = profiles.map((profile, index) => {
  const baseUsage = randomBetween(800, 2000);
  const csm = csms[index % csms.length];
  const tier = index < 3 ? 'enterprise' : (index < 7 ? 'growth' : 'starter');
  const mrr = tier === 'enterprise' ? randomBetween(4000, 8000) : (tier === 'growth' ? randomBetween(1000, 3000) : randomBetween(200, 800));

  return {
    // Account info
    account_id: `demo_${String(index + 1).padStart(3, '0')}`,
    account_name: companyNames[index],
    tier: tier,
    mrr: mrr,
    renewal_date: addDays(today, profile.renewal),
    csm_email: csm.email,
    csm_name: csm.name,
    champion_email: `champion@${companyNames[index].toLowerCase().replace(/\s+/g, '')}.com`,
    champion_name: `Champion ${index + 1}`,
    exec_sponsor_present: tier === 'enterprise' && profile.health === 'green',
    industry: ['SaaS', 'Finance', 'Healthcare', 'Retail', 'Manufacturing'][index % 5],
    employee_count: randomBetween(50, 500),

    // Usage signals
    usage_7d: Math.round(baseUsage * profile.usageMult * 0.25),
    usage_30d: Math.round(baseUsage * profile.usageMult),
    baseline_usage: baseUsage,
    dau_7d_avg: Math.round(randomBetween(5, 25) * profile.usageMult),
    feature_adoption_pct: profile.health === 'green' ? randomBetween(60, 85) : (profile.health === 'yellow' ? randomBetween(35, 55) : randomBetween(15, 35)),

    // Support signals
    tickets_7d_count: profile.tickets,
    tickets_7d_severity_weighted: profile.tickets * randomBetween(1, 3),
    tickets_30d_count: profile.tickets * 3,
    sla_breaches_30d: profile.health === 'red' ? randomBetween(1, 4) : 0,
    avg_resolution_hours: profile.health === 'green' ? randomBetween(4, 12) : (profile.health === 'yellow' ? randomBetween(18, 36) : randomBetween(48, 96)),
    open_tickets: Math.ceil(profile.tickets / 2),

    // Billing signals
    billing_failed_payments_30d: profile.failedPayments,
    downgrade_flag: profile.health === 'red' && index === 8,
    expansion_flag: profile.health === 'green',
    invoice_overdue_days: profile.failedPayments > 0 ? randomBetween(5, 20) : 0,

    // Sentiment signals
    nps_last: profile.nps,
    nps_date: addDays(today, -randomBetween(5, 30)),
    csat_last: profile.nps >= 8 ? randomBetween(40, 50) / 10 : (profile.nps >= 5 ? randomBetween(28, 38) / 10 : randomBetween(15, 28) / 10),
    sentiment_score: profile.sentiment,

    // Engagement signals
    days_since_last_csm_touch: profile.csmDays,
    champion_last_seen_days: profile.championDays,
    meetings_30d: profile.health === 'green' ? randomBetween(2, 4) : (profile.health === 'yellow' ? randomBetween(0, 2) : 0),
    emails_sent_30d: randomBetween(3, 10),
    emails_opened_30d: profile.health === 'green' ? randomBetween(3, 8) : randomBetween(0, 3),

    // Metadata
    _demo_profile: profile.health,
    _generated_at: new Date().toISOString()
  };
});

return accounts.map(acc => ({ json: acc }));

// Normalize accounts from different sources to standard format
const items = $input.all();

return items.map(item => {
  const data = item.json;

  // If already in standard format (demo or sheets), return as-is
  if (data.account_id) {
    return { json: data };
  }

  // HubSpot format
  if (data.hs_object_id) {
    return {
      json: {
        account_id: `hs_${data.hs_object_id}`,
        account_name: data.properties?.name || data.name,
        tier: data.properties?.customer_tier || 'growth',
        mrr: parseFloat(data.properties?.mrr) || 0,
        renewal_date: data.properties?.renewal_date,
        csm_email: data.properties?.hubspot_owner_id,
        crm_id: data.hs_object_id,
        crm_source: 'hubspot'
      }
    };
  }

  // Salesforce format
  if (data.Id && data.attributes?.type === 'Account') {
    return {
      json: {
        account_id: `sf_${data.Id}`,
        account_name: data.Name,
        tier: data.Account_Tier__c || 'growth',
        mrr: parseFloat(data.MRR__c) || 0,
        renewal_date: data.Contract_End_Date__c,
        csm_email: data.Owner?.Email,
        crm_id: data.Id,
        crm_source: 'salesforce'
      }
    };
  }

  // Return original if format unknown
  return { json: data };
});

// Pass through ALL accounts for signal collection
  const items = $input.all();
  return items.map(item => ({
    json: { ...item.json, _processing_started: new Date().toISOString() }
  }));

// Merge all signals for this account
const account = $('Start Account Processing').first().json;

// Helper to safely get first item from a node
function getSignals(nodeName) {
  try {
    const items = $(nodeName).all();
    if (items && items.length > 0) {
      return items[0].json;
    }
  } catch (e) {
    // Node didn't execute or had no output
  }
  return {};
}

// Collect from all enabled sources
const usage = getSignals('Sheets: Usage');
const tickets = getSignals('Sheets: Tickets');
const billing = getSignals('Sheets: Billing');
const sentiment = getSignals('Sheets: NPS/CSAT');

// For demo mode, account already has all signals
if (account._demo_profile) {
  return [{ json: account }];
}

// Merge signals into account
const mergedSignals = {
  ...account,

  // Usage (prefer existing account values if demo)
  usage_7d: account.usage_7d ?? usage.usage_7d ?? null,
  usage_30d: account.usage_30d ?? usage.usage_30d ?? null,
  baseline_usage: account.baseline_usage ?? usage.baseline_usage ?? null,
  dau_7d_avg: account.dau_7d_avg ?? usage.dau_7d_avg ?? null,
  feature_adoption_pct: account.feature_adoption_pct ?? usage.feature_adoption_pct ?? null,

  // Support
  tickets_7d_count: account.tickets_7d_count ?? tickets.tickets_7d_count ?? null,
  tickets_7d_severity_weighted: account.tickets_7d_severity_weighted ?? tickets.tickets_7d_severity_weighted ?? null,
  tickets_30d_count: account.tickets_30d_count ?? tickets.tickets_30d_count ?? null,
  sla_breaches_30d: account.sla_breaches_30d ?? tickets.sla_breaches_30d ?? null,
  avg_resolution_hours: account.avg_resolution_hours ?? tickets.avg_resolution_hours ?? null,
  open_tickets: account.open_tickets ?? tickets.open_tickets ?? null,

  // Billing
  billing_failed_payments_30d: account.billing_failed_payments_30d ?? billing.billing_failed_payments_30d ?? null,
  downgrade_flag: account.downgrade_flag ?? billing.downgrade_flag ?? false,
  expansion_flag: account.expansion_flag ?? billing.expansion_flag ?? false,
  invoice_overdue_days: account.invoice_overdue_days ?? billing.invoice_overdue_days ?? null,

  // Sentiment
  nps_last: account.nps_last ?? sentiment.nps_last ?? null,
  nps_date: account.nps_date ?? sentiment.nps_date ?? null,
  csat_last: account.csat_last ?? sentiment.csat_last ?? null,
  sentiment_score: account.sentiment_score ?? sentiment.sentiment_score ?? null,

  // Engagement (these come from account/CRM)
  days_since_last_csm_touch: account.days_since_last_csm_touch ?? null,
  champion_last_seen_days: account.champion_last_seen_days ?? null,
  meetings_30d: account.meetings_30d ?? null,
  emails_sent_30d: account.emails_sent_30d ?? null,
  emails_opened_30d: account.emails_opened_30d ?? null,

  _signals_merged_at: new Date().toISOString()
};

return [{ json: mergedSignals }];

// ============================================================================
// SCORING ENGINE - Full implementation
// ============================================================================

const config = $('Load Config').first().json;
const signals = $input.first().json;

// Config structure
const weights = {
  usage: config['weights.usage'] || 0.30,
  support: config['weights.support'] || 0.20,
  billing: config['weights.billing'] || 0.15,
  sentiment: config['weights.sentiment'] || 0.20,
  engagement: config['weights.engagement'] || 0.15
};

const thresholds = {
  green_min: config['thresholds.green_min'] || 70,
  yellow_min: config['thresholds.yellow_min'] || 40,
  usage_drop_pct: config['thresholds.usage_drop_pct'] || 20,
  usage_critical_drop_pct: config['thresholds.usage_critical_drop_pct'] || 40,
  ticket_spike_7d: config['thresholds.ticket_spike_7d'] || 5,
  ticket_spike_severity: config['thresholds.ticket_spike_severity'] || 10,
  sla_breach_threshold: config['thresholds.sla_breach_threshold'] || 2,
  engagement_gap_days: config['thresholds.engagement_gap_days'] || 14,
  champion_silent_days: config['thresholds.champion_silent_days'] || 21,
  renewal_warning_days: config['thresholds.renewal_warning_days'] || 60,
  renewal_critical_days: config['thresholds.renewal_critical_days'] || 30,
  nps_detractor_max: config['thresholds.nps_detractor_max'] || 6,
  nps_passive_max: config['thresholds.nps_passive_max'] || 8,
  csat_warning: config['thresholds.csat_warning'] || 3,
  sentiment_negative: config['thresholds.sentiment_negative'] || -0.2,
  failed_payment_threshold: config['thresholds.failed_payment_threshold'] || 1,
  feature_adoption_low_pct: config['thresholds.feature_adoption_low_pct'] || 30
};

const defaults = {
  usage_7d: 0, usage_30d: 0, baseline_usage: 100,
  tickets_7d: 0, nps: 7, csat: 3.5, sentiment: 0,
  csm_touch_days: 30, champion_days: 30
};

// Track missing data
const missingDataFlags = [];

// Normalize with defaults
const usage_7d = signals.usage_7d ?? defaults.usage_7d;
const usage_30d = signals.usage_30d ?? defaults.usage_30d;
const baseline_usage = signals.baseline_usage ?? defaults.baseline_usage;
const tickets_7d = signals.tickets_7d_count ?? defaults.tickets_7d;
const tickets_severity = signals.tickets_7d_severity_weighted ?? 0;
const sla_breaches = signals.sla_breaches_30d ?? 0;
const nps = signals.nps_last ?? defaults.nps;
const csat = signals.csat_last ?? defaults.csat;
const sentiment = signals.sentiment_score ?? defaults.sentiment;
const csm_touch_days = signals.days_since_last_csm_touch ?? defaults.csm_touch_days;
const champion_days = signals.champion_last_seen_days ?? defaults.champion_days;
const failed_payments = signals.billing_failed_payments_30d ?? 0;
const downgrade = signals.downgrade_flag ?? false;
const exec_sponsor = signals.exec_sponsor_present ?? false;
const feature_adoption = signals.feature_adoption_pct ?? 50;

if (signals.usage_7d === undefined) missingDataFlags.push('usage_7d');
if (signals.usage_30d === undefined) missingDataFlags.push('usage_30d');
if (signals.nps_last === undefined) missingDataFlags.push('nps');
if (signals.csat_last === undefined) missingDataFlags.push('csat');
if (signals.days_since_last_csm_touch === undefined) missingDataFlags.push('csm_touch');

// Days to renewal
const today = new Date();
const renewalDate = new Date(signals.renewal_date);
const daysToRenewal = Math.ceil((renewalDate - today) / (1000 * 60 * 60 * 24));

// ============================================================================
// COMPONENT SCORES
// ============================================================================

const scoreBreakdown = {
  usage_score: 0, usage_details: '',
  support_score: 0, support_details: '',
  billing_score: 0, billing_details: '',
  sentiment_score: 0, sentiment_details: '',
  engagement_score: 0, engagement_details: ''
};

// USAGE SCORE
let usageScore = 100;
const usageChange = baseline_usage > 0 ? ((usage_30d - baseline_usage) / baseline_usage) * 100 : 0;

if (usageChange < -thresholds.usage_critical_drop_pct) {
  usageScore = 20;
  scoreBreakdown.usage_details = `Critical drop: ${usageChange.toFixed(0)}% vs baseline`;
} else if (usageChange < -thresholds.usage_drop_pct) {
  usageScore = 50 + (usageChange + thresholds.usage_critical_drop_pct) * 1.5;
  scoreBreakdown.usage_details = `Declining: ${usageChange.toFixed(0)}% vs baseline`;
} else if (usageChange >= 0) {
  usageScore = Math.min(100, 80 + usageChange * 0.5);
  scoreBreakdown.usage_details = `Healthy: +${usageChange.toFixed(0)}% vs baseline`;
} else {
  usageScore = 70;
  scoreBreakdown.usage_details = `Slight dip: ${usageChange.toFixed(0)}% vs baseline`;
}

if (feature_adoption < thresholds.feature_adoption_low_pct) {
  usageScore = Math.max(20, usageScore - 20);
  scoreBreakdown.usage_details += `, Low adoption: ${feature_adoption}%`;
}
scoreBreakdown.usage_score = Math.round(usageScore);

// SUPPORT SCORE
let supportScore = 100;
if (tickets_7d >= thresholds.ticket_spike_7d) {
  supportScore -= 30;
  scoreBreakdown.support_details = `Ticket spike: ${tickets_7d} in 7d`;
}
if (tickets_severity >= thresholds.ticket_spike_severity) {
  supportScore -= 20;
  scoreBreakdown.support_details += (scoreBreakdown.support_details ? ', ' : '') + `High severity: ${tickets_severity}`;
}
if (sla_breaches >= thresholds.sla_breach_threshold) {
  supportScore -= 25;
  scoreBreakdown.support_details += (scoreBreakdown.support_details ? ', ' : '') + `SLA breaches: ${sla_breaches}`;
}
supportScore = Math.max(0, supportScore);
if (!scoreBreakdown.support_details) scoreBreakdown.support_details = `Healthy: ${tickets_7d} tickets, no SLA issues`;
scoreBreakdown.support_score = Math.round(supportScore);

// BILLING SCORE
let billingScore = 100;
if (failed_payments >= thresholds.failed_payment_threshold) {
  billingScore -= 40;
  scoreBreakdown.billing_details = `Failed payments: ${failed_payments}`;
}
if (downgrade) {
  billingScore -= 30;
  scoreBreakdown.billing_details += (scoreBreakdown.billing_details ? ', ' : '') + 'Downgrade pending';
}
if (signals.invoice_overdue_days && signals.invoice_overdue_days > 0) {
  billingScore -= Math.min(30, signals.invoice_overdue_days);
  scoreBreakdown.billing_details += (scoreBreakdown.billing_details ? ', ' : '') + `Invoice ${signals.invoice_overdue_days}d overdue`;
}
billingScore = Math.max(0, billingScore);
if (!scoreBreakdown.billing_details) scoreBreakdown.billing_details = 'Healthy: No billing issues';
scoreBreakdown.billing_score = Math.round(billingScore);

// SENTIMENT SCORE
let sentimentScore = 100;
if (nps <= thresholds.nps_detractor_max) {
  sentimentScore -= 40;
  scoreBreakdown.sentiment_details = `NPS Detractor: ${nps}`;
} else if (nps <= thresholds.nps_passive_max) {
  sentimentScore -= 15;
  scoreBreakdown.sentiment_details = `NPS Passive: ${nps}`;
} else {
  scoreBreakdown.sentiment_details = `NPS Promoter: ${nps}`;
}
if (csat < thresholds.csat_warning) {
  sentimentScore -= 25;
  scoreBreakdown.sentiment_details += `, Low CSAT: ${csat}`;
}
if (sentiment < thresholds.sentiment_negative) {
  sentimentScore -= 20;
  scoreBreakdown.sentiment_details += `, Negative sentiment: ${sentiment.toFixed(2)}`;
}
sentimentScore = Math.max(0, sentimentScore);
scoreBreakdown.sentiment_score = Math.round(sentimentScore);

// ENGAGEMENT SCORE
let engagementScore = 100;
if (csm_touch_days > thresholds.engagement_gap_days) {
  engagementScore -= 30;
  scoreBreakdown.engagement_details = `No CSM touch: ${csm_touch_days}d`;
}
if (champion_days > thresholds.champion_silent_days) {
  engagementScore -= 35;
  scoreBreakdown.engagement_details += (scoreBreakdown.engagement_details ? ', ' : '') + `Champion silent: ${champion_days}d`;
}
if (!exec_sponsor && signals.tier === 'enterprise') {
  engagementScore -= 15;
  scoreBreakdown.engagement_details += (scoreBreakdown.engagement_details ? ', ' : '') + 'No exec sponsor';
}
engagementScore = Math.max(0, engagementScore);
if (!scoreBreakdown.engagement_details) scoreBreakdown.engagement_details = `Healthy: CSM touch ${csm_touch_days}d ago`;
scoreBreakdown.engagement_score = Math.round(engagementScore);

// ============================================================================
// OVERALL SCORE & BAND
// ============================================================================

const healthScore = Math.round(
  scoreBreakdown.usage_score * weights.usage +
  scoreBreakdown.support_score * weights.support +
  scoreBreakdown.billing_score * weights.billing +
  scoreBreakdown.sentiment_score * weights.sentiment +
  scoreBreakdown.engagement_score * weights.engagement
);

let healthBand;
if (healthScore >= thresholds.green_min) healthBand = 'Green';
else if (healthScore >= thresholds.yellow_min) healthBand = 'Yellow';
else healthBand = 'Red';

// ============================================================================
// RISK REASONS
// ============================================================================

const riskReasons = [];
let priority = 1;

if (usageChange < -thresholds.usage_drop_pct) {
  riskReasons.push({
    code: 'usage_drop', name: 'Usage Drop',
    severity: usageChange < -thresholds.usage_critical_drop_pct ? 'critical' : 'high',
    priority: priority++,
    description: `Usage declined ${Math.abs(usageChange).toFixed(0)}% compared to baseline`,
    trigger_value: `${usageChange.toFixed(0)}%`, threshold: `-${thresholds.usage_drop_pct}%`
  });
}

if (tickets_7d >= thresholds.ticket_spike_7d || tickets_severity >= thresholds.ticket_spike_severity) {
  riskReasons.push({
    code: 'ticket_spike', name: 'Ticket Spike',
    severity: sla_breaches > 0 ? 'critical' : 'high',
    priority: priority++,
    description: `${tickets_7d} tickets in 7 days with severity score ${tickets_severity}`,
    trigger_value: `${tickets_7d} tickets`, threshold: `${thresholds.ticket_spike_7d} tickets`
  });
}

if (daysToRenewal <= thresholds.renewal_warning_days && healthScore < thresholds.green_min) {
  riskReasons.push({
    code: 'renewal_risk', name: 'Renewal Near + Low Engagement',
    severity: daysToRenewal <= thresholds.renewal_critical_days ? 'critical' : 'high',
    priority: priority++,
    description: `Renewal in ${daysToRenewal} days with health score ${healthScore}`,
    trigger_value: `${daysToRenewal} days`, threshold: `${thresholds.renewal_warning_days} days`
  });
}

if (champion_days > thresholds.champion_silent_days) {
  riskReasons.push({
    code: 'champion_silent', name: 'Champion Silent',
    severity: champion_days > thresholds.champion_silent_days * 2 ? 'critical' : 'high',
    priority: priority++,
    description: `Champion hasn't been active for ${champion_days} days`,
    trigger_value: `${champion_days} days`, threshold: `${thresholds.champion_silent_days} days`
  });
}

if (failed_payments >= thresholds.failed_payment_threshold || downgrade) {
  riskReasons.push({
    code: 'billing_friction', name: 'Billing Friction / Failed Payment',
    severity: failed_payments >= 2 ? 'critical' : 'high',
    priority: priority++,
    description: `${failed_payments} failed payments${downgrade ? ', downgrade pending' : ''}`,
    trigger_value: `${failed_payments} failures`, threshold: `${thresholds.failed_payment_threshold} failures`
  });
}

if (nps <= thresholds.nps_detractor_max || sentiment < thresholds.sentiment_negative) {
  riskReasons.push({
    code: 'poor_sentiment', name: 'Poor Sentiment (NPS/CSAT)',
    severity: nps <= 4 ? 'critical' : 'high',
    priority: priority++,
    description: `NPS: ${nps}, CSAT: ${csat}, Sentiment: ${sentiment.toFixed(2)}`,
    trigger_value: `NPS ${nps}`, threshold: `NPS > ${thresholds.nps_detractor_max}`
  });
}

if (feature_adoption < thresholds.feature_adoption_low_pct && (signals.meetings_30d === undefined || signals.meetings_30d < 2)) {
  riskReasons.push({
    code: 'implementation_stalled', name: 'Implementation Stalled',
    severity: feature_adoption < 20 ? 'critical' : 'medium',
    priority: priority++,
    description: `Only ${feature_adoption}% feature adoption with limited engagement`,
    trigger_value: `${feature_adoption}%`, threshold: `${thresholds.feature_adoption_low_pct}%`
  });
}

if (!exec_sponsor && signals.tier === 'enterprise' && daysToRenewal <= 90) {
  riskReasons.push({
    code: 'executive_misalignment', name: 'Executive Misalignment',
    severity: 'medium', priority: priority++,
    description: 'No executive sponsor identified for enterprise account approaching renewal',
    trigger_value: 'No sponsor', threshold: 'Sponsor required'
  });
}

if (missingDataFlags.length >= 3) {
  riskReasons.push({
    code: 'missing_data', name: 'Missing Data',
    severity: 'low', priority: 99,
    description: `Missing signals: ${missingDataFlags.join(', ')}`,
    trigger_value: `${missingDataFlags.length} fields`, threshold: '< 3 fields'
  });
}

// ============================================================================
// PLAYBOOKS
// ============================================================================

const playbookMappings = {
  usage_drop: ['re_engage_usage', 'schedule_training'],
  ticket_spike: ['support_escalation', 'root_cause_review'],
  renewal_risk: ['renewal_save_motion', 'exec_alignment'],
  champion_silent: ['re_engage_champion', 'identify_new_champion'],
  billing_friction: ['billing_resolution', 'payment_follow_up'],
  poor_sentiment: ['sentiment_recovery', 'feedback_review'],
  implementation_stalled: ['implementation_rescue', 'success_plan_review'],
  executive_misalignment: ['exec_sponsor_outreach', 'value_realization_review']
};

const playbooks = [];
const addedPlaybooks = new Set();

for (const risk of riskReasons) {
  const pbIds = playbookMappings[risk.code] || [];
  for (const pbId of pbIds) {
    if (!addedPlaybooks.has(pbId)) {
      addedPlaybooks.add(pbId);
      playbooks.push({
        id: pbId,
        name: pbId.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()),
        priority: risk.priority,
        triggered_by: risk.code
      });
    }
  }
}

// ============================================================================
// NEXT ACTION DATE & SUMMARY
// ============================================================================

let nextActionDays = 7;
if (healthBand === 'Red') nextActionDays = 1;
else if (healthBand === 'Yellow') nextActionDays = 3;
if (daysToRenewal <= 30) nextActionDays = Math.min(nextActionDays, 1);
else if (daysToRenewal <= 60) nextActionDays = Math.min(nextActionDays, 3);

const nextActionDate = new Date();
nextActionDate.setDate(nextActionDate.getDate() + nextActionDays);

// Generate summary
const sentences = [];
sentences.push(`${signals.account_name} health score is ${healthScore} (${healthBand}) with ${riskReasons.length} active risk${riskReasons.length !== 1 ? 's' : ''}.`);

if (riskReasons.length > 0) {
  sentences.push(`Primary concern: ${riskReasons[0].name} - ${riskReasons[0].description}.`);
} else {
  sentences.push('No significant risks detected at this time.');
}

const components = [
  ['Usage', scoreBreakdown.usage_score],
  ['Support', scoreBreakdown.support_score],
  ['Billing', scoreBreakdown.billing_score],
  ['Sentiment', scoreBreakdown.sentiment_score],
  ['Engagement', scoreBreakdown.engagement_score]
].sort((a, b) => a[1] - b[1]);

if (components[0][1] < 70) {
  sentences.push(`${components[0][0]} score (${components[0][1]}) is the weakest area requiring attention.`);
} else {
  sentences.push('All health components are performing adequately.');
}

if (daysToRenewal <= 30) {
  sentences.push(`URGENT: Renewal in ${daysToRenewal} days - immediate engagement required.`);
} else if (daysToRenewal <= 60) {
  sentences.push(`Renewal in ${daysToRenewal} days - begin renewal preparation now.`);
} else if (daysToRenewal <= 90) {
  sentences.push(`Renewal approaching in ${daysToRenewal} days - schedule QBR.`);
} else {
  sentences.push(`Renewal in ${daysToRenewal} days - no immediate timeline pressure.`);
}

if (healthBand === 'Red') {
  sentences.push('Recommend escalating to CS leadership and scheduling emergency account review.');
} else if (healthBand === 'Yellow') {
  sentences.push('Recommend proactive outreach within 48 hours to address identified risks.');
} else {
  sentences.push('Account is healthy - continue regular touchpoint cadence.');
}

// ============================================================================
// OUTPUT
// ============================================================================

return [{
  json: {
    // Account info
    account_id: signals.account_id,
    account_name: signals.account_name,
    tier: signals.tier,
    mrr: signals.mrr,
    csm_email: signals.csm_email,
    csm_name: signals.csm_name,

    // Scores
    health_score: healthScore,
    health_band: healthBand,
    score_breakdown: scoreBreakdown,

    // Risks & Actions
    risk_reasons: riskReasons,
    risk_count: riskReasons.length,
    top_risk: riskReasons[0]?.name || null,
    playbooks: playbooks,
    next_action_date: nextActionDate.toISOString().split('T')[0],

    // Summary
    summary_5_sentences: sentences.join(' '),
    days_to_renewal: daysToRenewal,
    missing_data_flags: missingDataFlags,

    // Metadata
    _scored_at: new Date().toISOString(),
    _signals: signals
  }
}];

// Generate tasks from playbooks
const result = $input.first().json;
const tasks = [];

for (const playbook of result.playbooks.slice(0, 3)) { // Limit to top 3 playbooks
  const taskName = `[${result.health_band}] ${result.account_name}: ${playbook.name}`;
  const description = [
    `Account: ${result.account_name}`,
    `Health Score: ${result.health_score} (${result.health_band})`,
    `Triggered by: ${playbook.triggered_by}`,
    ``,
    `Summary:`,
    result.summary_5_sentences,
    ``,
    `Playbook: ${playbook.name}`,
    `Priority: ${playbook.priority}`,
    ``,
    `Next Action Date: ${result.next_action_date}`
  ].join('\n');

  tasks.push({
    account_id: result.account_id,
    account_name: result.account_name,
    task_name: taskName,
    description: description,
    playbook: playbook.name,
    priority: playbook.priority,
    health_band: result.health_band,
    due_date: result.next_action_date,
    csm_email: result.csm_email
  });
}

return tasks.map(t => ({ json: t }));

// Collect all results for aggregation
const result = $('Scoring Engine').first().json;

return [{ json: result }];

// Generate summary statistics
const results = $input.all();
const runInfo = $('Initialize Run').first().json;

let green = 0, yellow = 0, red = 0;
const allRisks = [];
const errors = [];

for (const item of results) {
  const r = item.json;
  if (r.health_band === 'Green') green++;
  else if (r.health_band === 'Yellow') yellow++;
  else if (r.health_band === 'Red') red++;

  for (const risk of r.risk_reasons || []) {
    allRisks.push({
      account: r.account_name,
      risk: risk.name,
      severity: risk.severity
    });
  }
}

// Count top risks
const riskCounts = {};
for (const r of allRisks) {
  riskCounts[r.risk] = (riskCounts[r.risk] || 0) + 1;
}
const topRisks = Object.entries(riskCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([risk, count]) => `${risk} (${count})`);

// Red accounts for immediate attention
const redAccounts = results
  .filter(r => r.json.health_band === 'Red')
  .map(r => `${r.json.account_name} (${r.json.health_score})`)
  .slice(0, 5);

const summary = {
  run_id: runInfo.run_id,
  run_timestamp: runInfo.run_timestamp,
  accounts_processed: results.length,
  green_count: green,
  yellow_count: yellow,
  red_count: red,
  top_5_risks: topRisks,
  red_accounts: redAccounts,
  avg_health_score: Math.round(results.reduce((sum, r) => sum + r.json.health_score, 0) / results.length),
  errors: errors
};

return [{ json: summary }];

